// BFFEdgeServer is the server API for BFFEdge service.
// All implementations must embed UnimplementedBFFEdgeServer
// for forward compatibility.
//
// BFFEdge is the gateway service. RPC names mirror the underlying
// control-plane RPC where possible so the edge-side adapter is a
// thin one-liner per call. The exceptions are the four Subscribe*
// streams, which wrap NATS subjects, and ReportUsage, which wraps
// a NATS publish (the inverse direction).
type BFFEdgeServer interface {
	// ValidateToken is hot-path per session.
	ValidateToken(context.Context, *ValidateTokenRequest) (*ValidateTokenResponse, error)
	// RegisterEdgeNode is called by the edge on boot + heartbeat. bff-edge
	// OVERWRITES edge_node_id from the mTLS cert before forwarding.
	RegisterEdgeNode(context.Context, *RegisterEdgeNodeRequest) (*RegisterEdgeNodeResponse, error)
	// ReportClientPresence — same overwrite rule.
	ReportClientPresence(context.Context, *ReportClientPresenceRequest) (*ReportClientPresenceResponse, error)
	// GetOrgOnlineCount — admit-time check against max_online_clients.
	GetOrgOnlineCount(context.Context, *GetOrgOnlineCountRequest) (*GetOrgOnlineCountResponse, error)
	// ListEdges — the edge's mesh resolver polls this to build
	// its same-region peer address book. bff-edge FORCES the region filter
	// from the mTLS cert so an edge can only ever enumerate its own region.
	ListEdges(context.Context, *ListEdgesRequest) (*ListEdgesResponse, error)
	// CreateTunnel — edge-internal Persist path. bff-edge OVERWRITES the
	// request's edge_node_id field with the authenticated edge id.
	CreateTunnel(context.Context, *CreateTunnelRequest) (*Tunnel, error)
	// ClaimTunnel — overwrite edge_node_id.
	ClaimTunnel(context.Context, *ClaimTunnelRequest) (*Tunnel, error)
	// ReportStatus — overwrite edge_node_id.
	ReportStatus(context.Context, *ReportStatusRequest) (*ReportStatusResponse, error)
	// ListTunnels — fan-out queries the edge does to seed its
	// in-memory route table on boot. Org-scoped via the request,
	// not edge-scoped, so no overwrite.
	ListTunnels(context.Context, *ListTunnelsRequest) (*ListTunnelsResponse, error)
	// ListEdgeClaimedPorts — overwrite edge_node_id with caller id.
	ListEdgeClaimedPorts(context.Context, *ListEdgeClaimedPortsRequest) (*ListEdgeClaimedPortsResponse, error)
	// DeleteTunnel — used by the edge when a client disconnects with
	// ephemeral tunnels. No edge_node_id field; row-id authz lives in
	// tunnel-svc.
	DeleteTunnel(context.Context, *DeleteTunnelRequest) (*DeleteTunnelResponse, error)
	// Resolve — wildcard-DNS cross-edge lookup. No edge_node_id field.
	Resolve(context.Context, *ResolveRequest) (*ResolveResponse, error)
	// ResolveOwners — the region's {domain → owner edge} map
	// the mesh resolver polls to forward a visitor connection to the peer
	// that owns a subdomain this edge doesn't hold. Read-only, scoped by
	// base_domain (itself region-specific); no edge_node_id field.
	// ETag-style conditional poll via known_generation.
	ResolveOwners(context.Context, *ResolveOwnersRequest) (*ResolveOwnersResponse, error)
	// ReclaimTunnel — overwrite edge_node_id.
	ReclaimTunnel(context.Context, *ReclaimTunnelRequest) (*ReclaimTunnelResponse, error)
	// DrainEdge — overwrite edge_node_id with caller id.
	DrainEdge(context.Context, *DrainEdgeRequest) (*DrainEdgeResponse, error)
	// GetCert is edge-only (returns the decrypted private key). The mTLS
	// cert is the authz; bff-edge does not gate per-org here.
	GetCert(context.Context, *GetCertRequest) (*GetCertResponse, error)
	// ListCerts — same authz model.
	ListCerts(context.Context, *ListCertsRequest) (*ListCertsResponse, error)
	// RenewEdgeCert rotates the edge's OWN short-lived mTLS client cert before
	// it expires (F1, byoi-seat-and-cert-lifecycle). Unlike GetCert, bff-edge
	// GATES this per org: org + edge_node_id come from the authenticated mTLS
	// cert (never the body), and a fresh bundle is issued only while the org
	// still has BYOI entitlement (effective edge cap > 0 and org active). A
	// revoked cert can't reach here at all (mTLS/CRL) → revocation is a hard
	// cut; losing entitlement (e.g. downgrade to free with no purchased seats)
	// is a soft landing — renewal is refused and the short cert simply expires.
	// Reuses the edge's persisted region/public_addr; returns the same bundle
	// shape as issuance.
	RenewEdgeCert(context.Context, *RenewEdgeCertRequest) (*IssueEdgeCertResponse, error)
	GetEffectiveQuota(context.Context, *GetEffectiveRequest) (*EffectiveQuota, error)
	// ===== config-svc proxy (bidi stream) =====
	//
	// SubscribeConfig splices the edge's Subscribe stream to config-svc's
	// server-side stream. bff-edge does NOT inject ctx-based edge_id here
	// because HelloEdge (the first frame from the edge) already carries
	// edge_node_id — bff-edge verifies it matches the mTLS cert and
	// rejects the stream with PermissionDenied on mismatch.
	SubscribeConfig(grpc.BidiStreamingServer[EdgeMessage, ConfigMessage]) error
	SubscribeCertEvents(*SubscribeCertEventsRequest, grpc.ServerStreamingServer[CertEvent]) error
	SubscribeTunnelEvents(*SubscribeTunnelEventsRequest, grpc.ServerStreamingServer[TunnelEvent]) error
	SubscribeSessionEvictEvents(*SubscribeSessionEvictEventsRequest, grpc.ServerStreamingServer[SessionEvictEvent]) error
	// SubscribeUsageEvents bridges both calabi.usage.deny.> and
	// calabi.usage.allow.> in one stream. The edge filters on the
	// contained `kind` field locally.
	SubscribeUsageEvents(*SubscribeUsageEventsRequest, grpc.ServerStreamingServer[UsageEvent]) error
	// ===== Reverse direction: edge → NATS publish =====
	//
	// ReportUsage replaces the edge's direct NATS publish to
	// calabi.usage.report. bff-edge re-publishes on the cluster NATS
	// unchanged. Bulk-batched to amortize one mTLS RTT across many rows.
	ReportUsage(context.Context, *ReportUsageRequest) (*ReportUsageResponse, error)
	// ReportRelayUsage mirrors ReportUsage for a merged edge/relay node's OWN
	// mesh-relay traffic (edge/derp merge). bff-edge re-publishes each report on
	// the cluster NATS as calabi.usage.relay → metering-svc's relay_usage_raws.
	// The region carries a "self-<label>" code, which metering keeps OUT of the
	// plan cap: a customer's own relay is display-only.
	ReportRelayUsage(context.Context, *ReportRelayUsageRequest) (*ReportRelayUsageResponse, error)
	// RegisterRelay lets a merged edge/relay node self-register its relay endpoint
	// into the org's DERP map (edge/derp merge-B), mirroring how the edge
	// self-registers via RegisterEdgeNode. bff-edge derives the org from the mTLS
	// cert and idempotently upserts into coord (the node re-registers on a
	// heartbeat). The relay is self-hosted, so it lands under a "self-<label>"
	// region and never counts toward the plan cap.
	RegisterRelay(context.Context, *RegisterRelayRequest) (*RegisterRelayResponse, error)
	mustEmbedUnimplementedBFFEdgeServer()
}

